// Research-advice reports. Advice is generated by an agent (it costs LLM tokens),
// never by this website; the site only shows reports the owner chose to publish.
import { esc } from '../util.js';
import { renderMarkdown } from '../md.js';

export async function renderAdvice(main, ctx, { params }) {
  const reports = await ctx.getAdvice();
  const id = params[0];
  main.className = 'page page-advice';

  if (id) {
    const report = reports.find((r) => r.id === id);
    if (!report) {
      main.innerHTML = `<div class="notice"><h1>找不到這份建議報告</h1><p><a href="#/advice">回到研究建議</a></p></div>`;
      return;
    }
    main.innerHTML = `
      <article class="prose advice-report">
        <p class="crumb"><a href="#/advice">研究建議</a></p>
        <h1>${esc(report.title)}</h1>
        <p class="muted">${esc(report.created || '')}${report.stage ? `　研究階段：${esc(report.stage)}` : ''}</p>
        ${renderMarkdown(report.body, ctx.papers, 2)}
      </article>`;
    return;
  }

  main.innerHTML = `
    <div class="prose">
      <h1>研究建議</h1>
      <p>把你的研究題目與目前進度告訴 agent，它會依照固定的規則，從文獻庫與各篇 paper 的參考文獻裡找出對你有幫助的文獻，並給出下一步的建議。</p>
      <p>這個功能會消耗 LLM 額度，所以只能由有權限操作這個專案的 agent 執行，網站上不提供輸入表單。做法寫在<a href="#/guide">使用說明</a>。</p>
      <h2>已公開的報告</h2>
      ${reports.length ? `<ul class="report-list">${reports.map((r) => `
        <li><a href="#/advice/${esc(r.id)}">
          <span class="report-title">${esc(r.title)}</span>
          <span class="report-summary">${esc(r.summary || '')}</span>
          <span class="muted">${esc(r.created || '')}${r.stage ? `　${esc(r.stage)}` : ''}</span>
        </a></li>`).join('')}</ul>`
        : `<p class="muted">目前沒有公開的報告。建議報告預設只存在本機的 <code>advice-private/</code>，不會上傳；請 agent 產生報告時說「公開這份報告」，才會出現在這裡。</p>`}
    </div>`;
}
